INSERT INTO `board_news` (`id`, `title`, `content`, `writer`, `password`, `source`, `source_url`, `attachment`, `view_count`, `created_at`, `updated_at`) VALUES ('1', '철강 가격 동향 및 전망', '최근 국제 철강 가격이 상승세를 보이고 있습니다.\n\n중국의 생산 감축과 원자재 가격 상승이 주요 원인으로 분석됩니다.', '관리자', '1234', '한국철강신문', NULL, NULL, '203', '2025-08-05 01:52:35', '2026-01-29 05:37:15');
