INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('154', '강판 견적 요청드립니다', '건축 프로젝트용 강판 견적 요청합니다.\n\n필요 수량: 30톤\n규격: 6T x 1500 x 6000\n납품 위치: 충남 아산시\n납품 일정: 협의 가능\n\n경쟁력 있는 가격으로 제안 부탁드립니다.', '임**', '*28871D57A8DD5ECBADDB543CAEB2F89A1B20F308', '(주)LG인프라', '임팀장22@company.co.kr', '010-5325-3250', NULL, '0', '1', '견적 요청 확인했습니다.\n\n- 품목: 강판\n- 단가: 769,000원/톤\n- 합계: 192,250,000원\n- 납기: 12일\n\n경쟁력 있는 가격으로 공급 가능합니다.\n연락 부탁드립니다.', '2025-10-29 05:26:58', '2025-10-22 09:26:58', '2025-10-31 00:36:24', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('155', '강판 견적 문의', '건축 프로젝트용 강판 견적 요청합니다.\n\n필요 수량: 100톤\n규격: Ø60.5 x 3.2T\n납품 위치: 경기도 안양시\n납품 일정: 3주 이내\n\n경쟁력 있는 가격으로 제안 부탁드립니다.', '안**', '*C9A4FD0B2C3E652B17E20886348C8CD6E9CF0107', '금강토목', '안차장70@company.co.kr', '010-5759-4183', NULL, '0', '1', '견적 요청 확인했습니다.\n\n- 품목: 강판\n- 단가: 863,000원/톤\n- 합계: 215,750,000원\n- 납기: 9일\n\n경쟁력 있는 가격으로 공급 가능합니다.\n연락 부탁드립니다.', '2025-10-28 10:40:32', '2025-10-23 02:40:32', '2025-10-31 00:36:24', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('156', '철근(HD29) 견적 문의드립니다', '철근(HD29) 견적 요청드립니다.\n\n규격: H-350x350x12x19\n수량: 약 30톤\n납품지: 경북 구미시\n납기: 최대한 빨리\n\n자세한 견적서 부탁드립니다.', '강**', '*5070087744C19A91FF79BAC73DBADA7AE873CC84', '태영인프라', '강지영33@construction.com', '010-8734-9634', NULL, '0', '1', '안녕하세요.\n철근(HD29) 견적 회신드립니다.\n\n공급 단가: 863,000원/톤\n총 금액: 172,600,000원 (VAT 별도)\n납품 기간: 10일 소요\n\n추가 문의사항 있으시면 연락 주시기 바랍니다.', '2025-10-31 00:29:59', '2025-10-24 19:29:59', '2025-10-31 00:36:24', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('157', 'CR73kg/m 1,500m 견적요청건', '견적요청건\r\n\r\n1. 품목 : Rail\r\n2. 사향 :  73kg/m (MILL SHEET필요)\r\n3. 필요수량 : 1,500M (10M. 12M) 가능\r\n4. 필요일자 : 2026년 5월말\r\n5. 기타 : 중국산제외\r\n             중고A급 가능 (단 MILL SHEET필요)\r\n6. 납품자소 : 목포 대불공단내 (도착도)\r\n7. 결재 : 협의 ( 영세율/수출품)\r\n\r\n이상입니다.\r\n\r\n-끝-', '나경호 본부장', 'nkh1852318', '대상중공업주식회사', 'skrudgh1@hanmail.net', '010-8551-8649', '', '1', '1', '연락드리겠습니다.\r\n감사합니다.', '2026-01-07 08:03:44', '2026-01-06 03:53:46', '2026-01-07 08:03:44', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('159', '제품 견적 문의', '안녕하세요.\r\n\r\n제품 구입 견적 문의드립니다.\r\n\r\n1. H-BEAM \r\n    1). H150*150*7*10  = 1612kg\r\n    2). H200*100*5.5*8 = 1122kg\r\n    3). H250*125*6*9    = 1432kg\r\n2. C-CHANNEL\r\n    1). 100*50*20*2.3    = 406kg\r\n    2). 100*50*20*3.2    = 1420kg\r\n\r\n3. SQ-PIPE\r\n    1). 100*100*3.2       = 350kg\r\n\r\n4. R-BAR\r\n    1). 파이19               = 321kg\r\n\r\n운반비까지 포함인지 궁금합니다.\r\n\r\n감사합니다.', '하헌록', '3530', '개인사업자', 'haheonrok@gmail.com', '010-8109-4882', '', '5', '0', NULL, NULL, '2026-01-19 04:11:53', '2026-01-19 04:12:35', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('160', '사각파이프 및 철자재 견적 요청합니다', '철골 자재 견적 부탁합니다', '석병은', '0220', '새이레건축', 'sairearchi@naver.com', '010-3103-6643', '', '3', '0', NULL, NULL, '2026-01-22 03:02:40', '2026-01-22 03:03:08', NULL);
INSERT INTO `board_quote` (`id`, `title`, `content`, `writer`, `password`, `company`, `email`, `phone`, `attachment`, `view_count`, `is_answered`, `admin_reply`, `replied_at`, `created_at`, `updated_at`, `display_order`) VALUES ('161', '아연각관 견적 문의합니다.', '아연각관 소매업을 하려합니다. \r\n견적 금액 부탁드립니다.\r\n20*40 1.4\r\n50*50 1.4\r\n50*50 2.0\r\n100*50 2.0\r\n100*100 2.0\r\n100*100 2.9 입니다.', '고태범', 'tb061500', '우송건축자재', 'sinan8204@naver.com', '010-9938-9882', '', '0', '0', NULL, NULL, '2026-01-28 00:37:07', '2026-01-28 00:37:07', NULL);
INSERT INTO `calculation_constants` (`id`, `constant_name`, `constant_value`, `description`, `unit`, `is_editable`, `created_at`, `updated_at`) VALUES ('1', 'STEEL_DENSITY', '7850.0000000000', '철 밀도', 'kg/m³', '1', '2025-09-29 23:01:25', '2025-09-29 23:01:25');
INSERT INTO `calculation_constants` (`id`, `constant_name`, `constant_value`, `description`, `unit`, `is_editable`, `created_at`, `updated_at`) VALUES ('2', 'PI', '3.1415926536', '원주율', '', '0', '2025-09-29 23:01:25', '2025-09-29 23:01:25');
INSERT INTO `calculation_constants` (`id`, `constant_name`, `constant_value`, `description`, `unit`, `is_editable`, `created_at`, `updated_at`) VALUES ('3', 'STEEL_FACTOR_1', '0.0061700000', '철근 계산 계수 (d² × 0.00617)', '', '1', '2025-09-29 23:01:25', '2025-09-29 23:01:25');
INSERT INTO `calculation_constants` (`id`, `constant_name`, `constant_value`, `description`, `unit`, `is_editable`, `created_at`, `updated_at`) VALUES ('4', 'STEEL_FACTOR_2', '0.0078500000', '철판/평철 계산 계수', '', '1', '2025-09-29 23:01:25', '2025-09-29 23:01:25');
INSERT INTO `calculation_constants` (`id`, `constant_name`, `constant_value`, `description`, `unit`, `is_editable`, `created_at`, `updated_at`) VALUES ('5', 'STEEL_FACTOR_3', '0.0246600000', '원형파이프 계산 계수', '', '1', '2025-09-29 23:01:25', '2025-09-29 23:01:25');
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('1', '철근 중량 계산', 'rebar', NULL, '직경 기반 철근 중량 계산: 직경² × 0.00617 × 길이 × 수량', '{\"type\": \"expression\", \"expression\": \"(diameter * diameter) * STEEL_FACTOR_1 * length * quantity\", \"variables\": {\"diameter\": {\"source\": \"product\", \"field\": \"diameter\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_FACTOR_1\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '1', '2025-09-29 23:01:25', '2025-09-29 23:01:25', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('2', 'H형강 중량 계산', 'h-beam', NULL, '단위중량 기반 H형강 중량 계산: 본당중량(반올림) × 수량', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '2', '2025-09-29 23:01:25', '2025-09-29 23:01:25', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('3', '경량 H형강 중량 계산', 'light-h-beam', NULL, '단위중량 기반 경량 H형강 중량 계산', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '3', '2025-09-29 23:01:25', '2025-09-29 23:01:25', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('4', 'I형강 중량 계산', 'i-beam', NULL, '단위중량 기반 I형강 중량 계산', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '4', '2025-09-29 23:01:25', '2025-09-29 23:01:25', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('5', '철판 중량 계산', 'steel-plate', NULL, '두께 × 폭 × 길이 × 7.85 × 10⁻⁶ × 수량', '{\"type\": \"expression\", \"expression\": \"thickness * width * (length * 1000) * (STEEL_DENSITY / 1000000000) * quantity\", \"variables\": {\"thickness\": {\"source\": \"product\", \"field\": \"thickness\", \"required\": true}, \"width\": {\"source\": \"product\", \"field\": \"width\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_DENSITY\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '5', '2025-09-29 23:01:26', '2025-09-29 23:01:26', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('6', 'ㄱ형강 중량 계산', 'angle', NULL, '단위중량 × 길이 (소수점 둘째자리)', '{\"type\": \"expression\", \"expression\": \"unit_weight * length * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 2, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '6', '2025-09-29 23:01:26', '2025-09-29 23:01:26', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('7', '사각파이프 중량 계산', 'square-pipe', NULL, '[(외경둘레 - 4×두께) × 두께 × 0.00785] × 길이 × 수량', '{\"type\": \"expression\", \"expression\": \"((2 * (width + height)) - 4 * thickness) * thickness * STEEL_FACTOR_2 * length * quantity\", \"variables\": {\"width\": {\"source\": \"product\", \"field\": \"width\", \"required\": true}, \"height\": {\"source\": \"product\", \"field\": \"height\", \"required\": true}, \"thickness\": {\"source\": \"product\", \"field\": \"thickness\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_FACTOR_2\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '7', '2025-09-29 23:01:26', '2025-09-29 23:01:26', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('9', '철근 중량 계산', 'rebar', NULL, '직경 기반 철근 중량 계산: 직경² × 0.00617 × 길이 × 수량', '{\"type\": \"expression\", \"expression\": \"(diameter * diameter) * STEEL_FACTOR_1 * length * quantity\", \"variables\": {\"diameter\": {\"source\": \"product\", \"field\": \"diameter\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_FACTOR_1\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '1', '2025-09-29 23:01:35', '2025-09-29 23:01:35', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('10', 'H형강 중량 계산', 'h-beam', NULL, '단위중량 기반 H형강 중량 계산: 본당중량(반올림) × 수량', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '2', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('11', '경량 H형강 중량 계산', 'light-h-beam', NULL, '단위중량 기반 경량 H형강 중량 계산', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '3', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('12', 'I형강 중량 계산', 'i-beam', NULL, '단위중량 기반 I형강 중량 계산', '{\"type\": \"expression\", \"expression\": \"round(unit_weight * length, 1) * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 1, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_1_then_2', '1', '4', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('13', '철판 중량 계산', 'steel-plate', NULL, '두께 × 폭 × 길이 × 7.85 × 10⁻⁶ × 수량', '{\"type\": \"expression\", \"expression\": \"thickness * width * (length * 1000) * (STEEL_DENSITY / 1000000000) * quantity\", \"variables\": {\"thickness\": {\"source\": \"product\", \"field\": \"thickness\", \"required\": true}, \"width\": {\"source\": \"product\", \"field\": \"width\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_DENSITY\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '5', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('14', 'ㄱ형강 중량 계산', 'angle', NULL, '단위중량 × 길이 (소수점 둘째자리)', '{\"type\": \"expression\", \"expression\": \"unit_weight * length * quantity\", \"variables\": {\"unit_weight\": {\"source\": \"product\", \"field\": \"unit_weight\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"rounding\": {\"intermediate\": {\"step\": \"weight_per_piece\", \"decimals\": 2, \"method\": \"round\"}, \"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '6', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
INSERT INTO `calculation_formulas` (`id`, `formula_name`, `category_code`, `product_id`, `description`, `formula_expression`, `rounding_rule`, `is_active`, `display_order`, `created_at`, `updated_at`, `created_by`) VALUES ('15', '사각파이프 중량 계산', 'square-pipe', NULL, '[(외경둘레 - 4×두께) × 두께 × 0.00785] × 길이 × 수량', '{\"type\": \"expression\", \"expression\": \"((2 * (width + height)) - 4 * thickness) * thickness * STEEL_FACTOR_2 * length * quantity\", \"variables\": {\"width\": {\"source\": \"product\", \"field\": \"width\", \"required\": true}, \"height\": {\"source\": \"product\", \"field\": \"height\", \"required\": true}, \"thickness\": {\"source\": \"product\", \"field\": \"thickness\", \"required\": true}, \"length\": {\"source\": \"user_input\", \"required\": true}, \"quantity\": {\"source\": \"user_input\", \"required\": true}}, \"constants\": [\"STEEL_FACTOR_2\"], \"rounding\": {\"final\": {\"decimals\": 2, \"method\": \"round\"}}}', 'round_2', '1', '7', '2025-09-29 23:01:36', '2025-09-29 23:01:36', NULL);
