INSERT INTO `layer_popups` (`id`, `title`, `image_path`, `content`, `link_url`, `link_target`, `position_top`, `position_left`, `width`, `height`, `start_date`, `end_date`, `is_active`, `display_order`, `hide_today`, `created_at`, `updated_at`) VALUES ('1', '홈페이지 리뉴얼 안내', NULL, '<div style=\"text-align: center; padding: 30px 20px;\">\r\n<div style=\"margin-bottom: 20px;\">&nbsp;</div>\r\n<h2 style=\"color: #1a237e; font-size: 24px; margin-bottom: 20px; font-weight: bold;\">홈페이지 리뉴얼 안내</h2>\r\n<p style=\"color: #333; font-size: 16px; line-height: 1.8; margin-bottom: 25px;\">충남스틸 홈페이지가<br><strong>리뉴얼 작업 중</strong>입니다.</p>\r\n<div style=\"background: #f5f5f5; border-radius: 12px; padding: 20px; margin-bottom: 20px;\">\r\n<p style=\"color: #666; font-size: 14px; margin-bottom: 12px;\">문의사항은 아래로 연락 부탁드립니다.</p>\r\n<p style=\"margin: 8px 0;\"><span style=\"color: #666;\">대표전화</span> <a style=\"color: #1a237e; font-weight: bold; font-size: 18px; text-decoration: none; margin-left: 8px;\" href=\"tel:032-564-0090\">032-564-1616</a></p>\r\n<p style=\"margin: 8px 0;\"><span style=\"color: #666;\">핸드폰</span> <a style=\"color: #1a237e; font-weight: bold; font-size: 18px; text-decoration: none; margin-left: 8px;\" href=\"tel:010-9820-0495\">010-9820-0495</a></p>\r\n</div>\r\n<p style=\"color: #999; font-size: 13px;\">더 나은 서비스로 찾아뵙겠습니다.<br>감사합니다.</p>\r\n</div>', '', '_self', '100', '100', '420', '480', '2026-01-05', '2026-03-01', '1', '0', '1', '2026-01-05 02:39:12', '2026-01-07 01:59:43');
INSERT INTO `layer_popups` (`id`, `title`, `image_path`, `content`, `link_url`, `link_target`, `position_top`, `position_left`, `width`, `height`, `start_date`, `end_date`, `is_active`, `display_order`, `hide_today`, `created_at`, `updated_at`) VALUES ('2', '시즌 인사', '', '<div style=\"background: linear-gradient(135deg, rgb(168, 237, 234) 0%, rgb(254, 214, 227) 100%); padding: 40px 30px; text-align: center; user-select: auto !important;\">\r\n    <div style=\"font-size: 56px; margin-bottom: 16px; user-select: auto !important;\">🎊</div>\r\n    <h2 style=\"font-size: 28px; font-weight: 700; color: rgb(51, 51, 51); margin: 0px 0px 12px; user-select: auto !important;\">새해 복 많이 받으세요!</h2>\r\n    <p style=\"font-size: 16px; color: rgb(102, 102, 102); margin: 0px 0px 24px; user-select: auto !important;\">2026년 병오년 새해가 밝았습니다</p>\r\n    <div style=\"background: white; padding: 24px; border-radius: 16px; box-shadow: rgba(0, 0, 0, 0.08) 0px 4px 20px; user-select: auto !important;\">\r\n        <p style=\"font-size: 15px; color: rgb(85, 85, 85); line-height: 1.8; margin: 0px; user-select: auto !important;\">\r\n            항상 충남스틸을 이용해 주시는<br style=\"user-select: auto !important;\">\r\n            고객님께 깊은 감사를 드리며,<br style=\"user-select: auto !important;\">\r\n            새해에도 건강과 행복이<br style=\"user-select: auto !important;\">\r\n            가득하시길 기원합니다.\r\n        </p>\r\n        <div style=\"margin-top: 20px; font-size: 14px; color: rgb(136, 136, 136); user-select: auto !important;\">\r\n            - 충남스틸 임직원 일동 -\r\n        </div>\r\n    </div>\r\n</div>', '', '_self', '100', '600', '400', '440', NULL, NULL, '0', '0', '1', '2026-01-07 10:17:04', '2026-01-28 03:46:03');
