-- 테이블 구조: `calculation_constants`
-- -------------------------------------------------

DROP TABLE IF EXISTS `calculation_constants`;
CREATE TABLE `calculation_constants` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `constant_name` varchar(50) NOT NULL COMMENT '상수명 (STEEL_DENSITY 등)',
  `constant_value` decimal(20,10) NOT NULL COMMENT '상수값',
  `description` text DEFAULT NULL COMMENT '설명',
  `unit` varchar(20) DEFAULT NULL COMMENT '단위',
  `is_editable` tinyint(1) DEFAULT 1 COMMENT '수정 가능 여부',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '생성일',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일',
  PRIMARY KEY (`id`),
  UNIQUE KEY `constant_name` (`constant_name`),
  KEY `idx_constant_name` (`constant_name`)
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='계산 상수 관리';

-- 데이터 덤프: `calculation_constants`

-- -------------------------------------------------
-- 테이블 구조: `calculation_formulas`
-- -------------------------------------------------

DROP TABLE IF EXISTS `calculation_formulas`;
CREATE TABLE `calculation_formulas` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `formula_name` varchar(100) NOT NULL COMMENT '계산식 이름',
  `category_code` varchar(50) DEFAULT NULL COMMENT '카테고리 코드 (NULL이면 공용)',
  `product_id` int(11) DEFAULT NULL COMMENT '제품 ID (NULL이면 카테고리 전체 적용)',
  `description` text DEFAULT NULL COMMENT '계산식 설명',
  `formula_expression` text NOT NULL COMMENT '계산식 (JSON 형식)',
  `rounding_rule` varchar(20) DEFAULT 'round_2' COMMENT '반올림 규칙',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성화 여부',
  `display_order` int(11) DEFAULT 0 COMMENT '표시 순서',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '생성일',
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp() COMMENT '수정일',
  `created_by` int(11) DEFAULT NULL COMMENT '생성 관리자 ID',
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_category_product` (`category_code`,`product_id`),
  KEY `idx_category` (`category_code`),
  KEY `idx_product` (`product_id`),
  KEY `idx_is_active` (`is_active`),
  CONSTRAINT `calculation_formulas_ibfk_1` FOREIGN KEY (`category_code`) REFERENCES `product_categories` (`category_code`) ON DELETE CASCADE,
  CONSTRAINT `calculation_formulas_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='제품 계산식 정의';

-- 데이터 덤프: `calculation_formulas`

-- -------------------------------------------------
-- 테이블 구조: `calculation_history`
-- -------------------------------------------------

DROP TABLE IF EXISTS `calculation_history`;
CREATE TABLE `calculation_history` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `formula_id` int(11) NOT NULL COMMENT '계산식 ID',
  `version` int(11) NOT NULL DEFAULT 1 COMMENT '버전',
  `formula_expression` text NOT NULL COMMENT '변경된 계산식',
  `parameters_snapshot` text DEFAULT NULL COMMENT '파라미터 스냅샷 (JSON)',
  `changed_by` int(11) DEFAULT NULL COMMENT '변경한 관리자 ID',
  `change_description` text DEFAULT NULL COMMENT '변경 사유',
  `created_at` timestamp NULL DEFAULT current_timestamp() COMMENT '생성일',
  PRIMARY KEY (`id`),
  KEY `idx_formula` (`formula_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_version` (`formula_id`,`version`),
  CONSTRAINT `calculation_history_ibfk_1` FOREIGN KEY (`formula_id`) REFERENCES `calculation_formulas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='계산식 변경 이력';

-- -------------------------------------------------
-- 테이블 구조: `calculation_logs`
-- -------------------------------------------------

DROP TABLE IF EXISTS `calculation_logs`;
CREATE TABLE `calculation_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `category_code` varchar(50) NOT NULL,
  `specification` varchar(100) DEFAULT NULL,
  `material` varchar(50) DEFAULT NULL,
  `length` decimal(10,2) DEFAULT NULL,
  `quantity` int(11) DEFAULT NULL,
  `calculated_weight` decimal(10,2) DEFAULT NULL,
  `user_ip` varchar(45) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_product` (`product_id`),
  KEY `idx_created` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 데이터 덤프: `calculation_logs`

-- -------------------------------------------------
-- 테이블 구조: `calculation_parameters`
-- -------------------------------------------------

DROP TABLE IF EXISTS `calculation_parameters`;
CREATE TABLE `calculation_parameters` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `formula_id` int(11) NOT NULL COMMENT '계산식 ID',
  `parameter_name` varchar(50) NOT NULL COMMENT '파라미터 명 (length, quantity 등)',
  `parameter_label` varchar(100) NOT NULL COMMENT '표시 라벨',
  `parameter_type` enum('number','select','text','product_field') DEFAULT 'number' COMMENT '파라미터 타입',
  `source_field` varchar(50) DEFAULT NULL COMMENT '제품 테이블 필드명 (type이 product_field인 경우)',
  `default_value` varchar(100) DEFAULT NULL COMMENT '기본값',
  `min_value` decimal(10,2) DEFAULT NULL COMMENT '최소값',
  `max_value` decimal(10,2) DEFAULT NULL COMMENT '최대값',
  `step_value` decimal(10,2) DEFAULT NULL COMMENT '증감 단위',
  `unit` varchar(20) DEFAULT NULL COMMENT '단위 (m, kg, mm 등)',
  `validation_rule` text DEFAULT NULL COMMENT '유효성 검사 규칙 (JSON)',
  `options` text DEFAULT NULL COMMENT '선택 옵션 (JSON, type이 select인 경우)',
  `display_order` int(11) DEFAULT 0 COMMENT '표시 순서',
  `is_required` tinyint(1) DEFAULT 1 COMMENT '필수 여부',
  PRIMARY KEY (`id`),
  KEY `idx_formula` (`formula_id`),
  KEY `idx_display_order` (`display_order`),
  CONSTRAINT `calculation_parameters_ibfk_1` FOREIGN KEY (`formula_id`) REFERENCES `calculation_formulas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='계산식 파라미터 정의';

-- 데이터 덤프: `calculation_parameters`

