-- 테이블 구조: `product_delete_logs`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_delete_logs`;
CREATE TABLE `product_delete_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `product_name` varchar(200) NOT NULL,
  `category_code` varchar(50) DEFAULT NULL,
  `specifications` text DEFAULT NULL,
  `deleted_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`deleted_data`)),
  `deleted_by` varchar(100) DEFAULT NULL,
  `deleted_via` varchar(50) DEFAULT 'csv_import',
  `deleted_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 데이터 덤프: `product_delete_logs`

-- -------------------------------------------------
-- 테이블 구조: `product_icons`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_icons`;
CREATE TABLE `product_icons` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_code` varchar(50) DEFAULT NULL,
  `icon_name` varchar(100) NOT NULL COMMENT '아이콘 표시명',
  `icon_image` varchar(500) DEFAULT NULL COMMENT '아이콘 이미지 경로',
  `icon_url` varchar(500) DEFAULT NULL COMMENT '클릭시 이동할 URL',
  `url_target` enum('_self','_blank') DEFAULT '_self' COMMENT 'URL 타겟 (현재창/새창)',
  `display_order` int(11) DEFAULT 0 COMMENT '표시 순서',
  `is_active` tinyint(1) DEFAULT 1 COMMENT '활성화 여부',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_display_order` (`display_order`),
  KEY `idx_is_active` (`is_active`)
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='메인페이지 제품 아이콘 관리';

-- 데이터 덤프: `product_icons`

-- -------------------------------------------------
-- 테이블 구조: `product_images`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_images`;
CREATE TABLE `product_images` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `image_url` varchar(500) NOT NULL,
  `image_type` enum('main','detail','spec') DEFAULT 'detail',
  `display_order` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `product_images_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------
-- 테이블 구조: `product_quote_items`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_quote_items`;
CREATE TABLE `product_quote_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `quote_id` int(11) NOT NULL COMMENT '견적 ID',
  `product_id` int(11) DEFAULT NULL COMMENT '제품 ID',
  `product_name` varchar(200) NOT NULL COMMENT '제품명',
  `product_spec` varchar(200) DEFAULT NULL COMMENT '규격',
  `quantity` int(11) DEFAULT 1 COMMENT '수량',
  `unit_price` decimal(12,2) DEFAULT 0.00 COMMENT '단가',
  `subtotal` decimal(12,2) DEFAULT 0.00 COMMENT '소계',
  `note` text DEFAULT NULL COMMENT '비고',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_quote` (`quote_id`),
  KEY `idx_product` (`product_id`),
  CONSTRAINT `product_quote_items_ibfk_1` FOREIGN KEY (`quote_id`) REFERENCES `product_quotes` (`id`) ON DELETE CASCADE,
  CONSTRAINT `product_quote_items_ibfk_2` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='제품 견적 상세 항목';

-- 데이터 덤프: `product_quote_items`

-- -------------------------------------------------
-- 테이블 구조: `product_quotes`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_quotes`;
CREATE TABLE `product_quotes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(100) NOT NULL COMMENT '고객명',
  `company` varchar(200) DEFAULT NULL COMMENT '회사명',
  `phone` varchar(20) NOT NULL COMMENT '연락처',
  `email` varchar(100) DEFAULT NULL COMMENT '이메일',
  `address` varchar(500) DEFAULT NULL COMMENT '주소',
  `address_detail` varchar(200) DEFAULT NULL COMMENT '상세주소',
  `products` text DEFAULT NULL COMMENT '제품 요약',
  `total_amount` decimal(12,2) DEFAULT 0.00 COMMENT '총 금액',
  `status` enum('pending','processing','completed','cancelled') DEFAULT 'pending' COMMENT '상태',
  `admin_note` text DEFAULT NULL COMMENT '관리자 메모',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_created` (`created_at`),
  KEY `idx_customer` (`customer_name`),
  KEY `idx_phone` (`phone`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='제품 견적 요청';

-- 데이터 덤프: `product_quotes`

-- -------------------------------------------------
-- 테이블 구조: `product_specifications`
-- -------------------------------------------------

DROP TABLE IF EXISTS `product_specifications`;
CREATE TABLE `product_specifications` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `category_code` varchar(50) NOT NULL,
  `specification` varchar(100) NOT NULL COMMENT '규격 (예: 25*25*3T)',
  `unit_weight` decimal(10,3) NOT NULL COMMENT '단위중량 (kg)',
  `material` varchar(50) DEFAULT NULL COMMENT '재질',
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `product_id` (`product_id`),
  KEY `idx_category` (`category_code`),
  KEY `idx_spec` (`specification`),
  KEY `idx_material` (`material`),
  CONSTRAINT `product_specifications_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- -------------------------------------------------
-- 테이블 구조: `products`
-- -------------------------------------------------

DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_code` varchar(50) NOT NULL,
  `product_name` varchar(200) NOT NULL,
  `product_code` varchar(100) DEFAULT NULL,
  `specifications` text DEFAULT NULL,
  `description` text DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `price_unit` varchar(10) DEFAULT 'kg' COMMENT '가격 단위: kg 또는 piece',
  `unit` varchar(50) DEFAULT NULL,
  `min_order_qty` int(11) DEFAULT 1,
  `base_length` int(11) DEFAULT 6 COMMENT '기준길이(m)',
  `stock_status` enum('in_stock','out_of_stock','on_order') DEFAULT 'in_stock',
  `main_image` varchar(500) DEFAULT NULL,
  `detail_images` text DEFAULT NULL,
  `features` text DEFAULT NULL,
  `dimensions` text DEFAULT NULL,
  `weight` varchar(100) DEFAULT NULL,
  `material` varchar(200) DEFAULT NULL,
  `length` decimal(5,1) DEFAULT NULL,
  `manufacturer` varchar(200) DEFAULT NULL,
  `origin` varchar(100) DEFAULT NULL,
  `delivery_info` text DEFAULT NULL,
  `is_featured` tinyint(1) DEFAULT 0,
  `is_active` tinyint(1) DEFAULT 1,
  `view_count` int(11) DEFAULT 0,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `calculation_type` enum('linear','sheet','piece') DEFAULT 'linear',
  `unit_weight_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '규격별 단위중량 데이터' CHECK (json_valid(`unit_weight_data`)),
  `available_materials` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '사용 가능한 재질 목록' CHECK (json_valid(`available_materials`)),
  `available_sizes` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '사용 가능한 규격 목록' CHECK (json_valid(`available_sizes`)),
  `has_calculator` tinyint(1) DEFAULT 0 COMMENT '계산기 사용 여부',
  `display_mode` enum('single','by_specification') DEFAULT 'single' COMMENT '표시 모드: single(단일), by_specification(규격별)',
  `parent_product_id` int(11) DEFAULT NULL COMMENT '부모 제품 ID (규격별 제품인 경우)',
  `specification` varchar(100) DEFAULT NULL COMMENT '개별 규격 (규격별 제품인 경우)',
  `specification_weight` decimal(10,3) DEFAULT NULL COMMENT '해당 규격의 단위중량',
  `origin_price_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '원산지별 추가 가격 데이터' CHECK (json_valid(`origin_price_data`)),
  `material_price_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '재질별 추가 가격 데이터' CHECK (json_valid(`material_price_data`)),
  `available_origins` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '사용 가능한 원산지 목록' CHECK (json_valid(`available_origins`)),
  `show_on_homepage` tinyint(1) DEFAULT 0 COMMENT '홈페이지 표시 여부',
  `homepage_display_order` int(11) DEFAULT 0 COMMENT '홈페이지 표시 순서',
  `min_length` decimal(10,2) DEFAULT NULL COMMENT '최소 길이(m)',
  `max_length` decimal(10,2) DEFAULT NULL COMMENT '최대 길이(m)',
  `standard_length` decimal(10,2) DEFAULT NULL COMMENT '표준 길이(m)',
  `rebar_manual_min_price` decimal(12,0) DEFAULT NULL COMMENT '철근 수동 최저가격(번들기준,원)',
  `rebar_manual_max_price` decimal(12,0) DEFAULT NULL COMMENT '철근 수동 최대가격(번들기준,원)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `product_code` (`product_code`),
  KEY `category_code` (`category_code`),
  KEY `idx_parent_product` (`parent_product_id`),
  KEY `idx_specification` (`specification`),
  CONSTRAINT `fk_parent_product` FOREIGN KEY (`parent_product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`category_code`) REFERENCES `product_categories` (`category_code`)
) ENGINE=InnoDB AUTO_INCREMENT=1464 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 데이터 덤프: `products`

-- -------------------------------------------------
-- 테이블 구조: `rebar_length_data`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_length_data`;
CREATE TABLE `rebar_length_data` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `spec_name` varchar(50) NOT NULL,
  `length` decimal(5,1) NOT NULL,
  `piece_weight` decimal(10,3) DEFAULT NULL,
  `pieces_per_length` int(11) DEFAULT NULL,
  `weight_per_ton` decimal(10,1) DEFAULT NULL,
  `unit_weight` decimal(10,3) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_spec_length` (`spec_name`,`length`)
) ENGINE=InnoDB AUTO_INCREMENT=2093 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 데이터 덤프: `rebar_length_data`

-- -------------------------------------------------
-- 테이블 구조: `rebar_length_data_backup`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_length_data_backup`;
CREATE TABLE `rebar_length_data_backup` (
  `id` int(11) NOT NULL DEFAULT 0,
  `spec_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `length` decimal(5,1) NOT NULL,
  `piece_weight` decimal(10,3) DEFAULT NULL,
  `pieces_per_ton` int(11) DEFAULT NULL,
  `weight_per_ton` decimal(10,1) DEFAULT NULL,
  `unit_weight` decimal(10,3) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 데이터 덤프: `rebar_length_data_backup`

-- -------------------------------------------------
-- 테이블 구조: `rebar_length_info`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_length_info`;
CREATE TABLE `rebar_length_info` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `spec_id` int(11) NOT NULL,
  `length` decimal(5,1) NOT NULL,
  `pieces_per_ton` int(11) NOT NULL,
  `total_weight` decimal(10,1) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_spec_length` (`spec_id`,`length`),
  CONSTRAINT `rebar_length_info_ibfk_1` FOREIGN KEY (`spec_id`) REFERENCES `rebar_specifications` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -------------------------------------------------
-- 테이블 구조: `rebar_materials`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_materials`;
CREATE TABLE `rebar_materials` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `material_name` varchar(50) NOT NULL,
  `price_per_kg` decimal(10,2) DEFAULT 0.00,
  `description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `is_active` tinyint(1) DEFAULT 1,
  `display_order` int(11) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `material_name` (`material_name`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 데이터 덤프: `rebar_materials`

-- -------------------------------------------------
-- 테이블 구조: `rebar_prices`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_prices`;
CREATE TABLE `rebar_prices` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `spec_name` varchar(50) NOT NULL,
  `origin` varchar(100) DEFAULT NULL,
  `manufacturer` varchar(100) DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `price_date` date DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT 1,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_spec_origin` (`spec_name`,`origin`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- 데이터 덤프: `rebar_prices`

-- -------------------------------------------------
-- 테이블 구조: `rebar_products`
-- -------------------------------------------------

DROP TABLE IF EXISTS `rebar_products`;
CREATE TABLE `rebar_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `spec_id` int(11) NOT NULL,
  `material_id` int(11) DEFAULT NULL,
  `origin` varchar(100) DEFAULT NULL,
  `manufacturer` varchar(100) DEFAULT NULL,
  `stock_status` varchar(50) DEFAULT NULL,
  `price` decimal(12,2) DEFAULT NULL,
  `available_origins` text DEFAULT NULL,
  `stock_types` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `spec_id` (`spec_id`),
  KEY `material_id` (`material_id`),
  CONSTRAINT `rebar_products_ibfk_1` FOREIGN KEY (`spec_id`) REFERENCES `rebar_specifications` (`id`),
  CONSTRAINT `rebar_products_ibfk_2` FOREIGN KEY (`material_id`) REFERENCES `rebar_materials` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

